import java.util.*;

public class Main {
    boolean isHappy(int n) {
        Set<Integer> seen = new HashSet<>();      // remember every number we've already visited
        while (n != 1 && !seen.contains(n)) {
            seen.add(n);                             // mark this number as visited
            int total = 0;
            while (n > 0) {
                int digit = n % 10;
                total += digit * digit;                // add the square of each digit
                n /= 10;
            }
            n = total;                                 // move to the next number in the sequence
        }
        return n == 1;                                // true only if we stopped because we hit 1
    }

    public static void main(String[] args) {
        int n = 19;
        Main solution = new Main();
        System.out.println(solution.isHappy(n));
    }
}

