import java.util.*;

public class Main {
    int getNext(int n) {
        int total = 0;
        while (n > 0) {
            int digit = n % 10;
            total += digit * digit;          // add the square of each digit
            n /= 10;
        }
        return total;
    }

    boolean isHappy(int n) {
        int slow = n;                       // moves one step at a time
        int fast = getNext(n);              // moves two steps at a time, starts one step ahead
        while (fast != 1 && slow != fast) {
            slow = getNext(slow);             // advance slow by one step
            fast = getNext(getNext(fast));    // advance fast by two steps
        }
        return fast == 1;                   // true only if the fast runner reached 1
    }

    public static void main(String[] args) {
        int n = 19;
        Main solution = new Main();
        System.out.println(solution.isHappy(n));
    }
}

